parameters.jsCode:
const body = $('Webhook').first().json.body;
const code = body.code || '';
const instruction = body.instruction || '';

if (!code) throw new Error('code is required');
if (!instruction) throw new Error('instruction is required');

const systemPrompt = [
  'You are an expert at editing JavaScript canvas animation code.',
  'The user will give you existing canvas infographic code and an edit instruction.',
  'Apply the requested change precisely and return ONLY the modified JavaScript code.',
  'Do not wrap in markdown, do not add explanations, do not change anything not mentioned in the instruction.',
  'The code must retain the exact same function signature: function drawGraphic(ctx, width, height, logoImg, options)',
  'Return a valid JSON object: { "jsCode": "...complete updated code..." }',
  'No markdown. No code fences.',
].join('\n');

const userPrompt = 'Current code:\n' + code + '\n\nEdit instruction: ' + instruction + '\n\nReturn only the updated code as JSON { "jsCode": "..." }';

const requestBody = JSON.stringify({
  model: 'google/gemini-3.5-flash',
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: userPrompt }
  ],
  max_tokens: 32000
});

return [{ json: { requestBody } }];

const aiResponse = $('Call AI').first().json;

const raw = aiResponse.choices?.[0]?.message?.content;
if (!raw) throw new Error('No content from AI: ' + JSON.stringify(aiResponse));

let cleaned = raw.trim();
if (cleaned.startsWith('```')) {
  cleaned = cleaned.replace(/^```[\w]*\n?/, '').replace(/\n?```$/, '').trim();
}

function fixJsonEscapes(str) {
  return str.replace(/\\(?!["\\/bfnrtu])/g, '\\\\');
}

let jsCode = null;
try {
  const parsed = JSON.parse(cleaned);
  jsCode = parsed.jsCode || null;
} catch(e) {
  try {
    const parsed = JSON.parse(fixJsonEscapes(cleaned));
    jsCode = parsed.jsCode || null;
  } catch(e2) {
    // Model returned raw code instead of JSON — use as-is
    jsCode = cleaned;
  }
}

if (!jsCode) throw new Error('Could not extract jsCode from AI response');

// Actually constructs AND calls the code (a thrown/parse error inside `new Function(body)` only
// surfaces once the function runs) to confirm drawGraphic both parses and gets defined — this
// stops a broken edit from ever reaching the client and getting saved as the new generatedCode,
// where it would keep breaking every subsequent render/animate/download silently.
function isValidDrawGraphic(code) {
  try {
    const result = new Function(code + "\nreturn typeof drawGraphic==='function';")();
    return result === true;
  } catch (e) {
    return false;
  }
}

if (!isValidDrawGraphic(jsCode)) {
  throw new Error('The edit produced invalid code. Please try rephrasing the instruction.');
}

return [{ json: { jsCode } }];
